def parse_minutes(text):
    try:
        value = int(text)
    except ValueError:
        return {"status": "invalid text", "value": None}
    if value < 0 or value > 60:
        return {"status": "out of range", "value": None}
    return {"status": "ok", "value": value}

for text in ["12", "zero", "0", "61"]:
    print(parse_minutes(text))
